{
  "servers": {
    "upstash": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@upstash/mcp-server@latest",
        "--email",
        "YOUR_EMAIL",
        "--api-key",
        "YOUR_API_KEY"
      ],
      "env": {
        "UPSTASH_EMAIL": "<YOUR_UPSTASH_EMAIL>",
        "UPSTASH_API_KEY": "${input:upstash-api-key}",
        "UPSTASH_BOX_API_KEY": "${input:upstash-box-api-key}"
      }
    }
  },
  "inputs": [
    {
      "type": "promptString",
      "id": "upstash-api-key",
      "description": "UPSTASH_API_KEY",
      "password": true
    },
    {
      "type": "promptString",
      "id": "upstash-box-api-key",
      "description": "UPSTASH_BOX_API_KEY",
      "password": true
    }
  ]
}
